 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
begin
  new.updated_at := now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.tg_pe_ai_message()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_sport text;
begin
  if new.role = 'user' then
    select sport into v_sport from public.ai_conversations where id = new.conversation_id;
    perform public.log_product_event(new.user_id, 'rombot_message_sent',
      jsonb_build_object('conversation_id', new.conversation_id, 'chars', length(coalesce(new.content, ''))), v_sport);
  end if;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION public.tg_pe_assessment_inserted()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_measured int; v_prior int;
begin
  select count(*) into v_measured from jsonb_each_text(to_jsonb(new)) e
   where e.value is not null and (e.key like 'hip_%' or e.key like 'shoulder_%' or e.key like 'ankle_%' or e.key like 'cervical_%' or e.key like 'lumbar_%' or e.key like 'thoracic_%' or e.key like 'balance_%');
  select count(*) into v_prior from public.assessments a where a.user_id = new.user_id and a.id <> new.id;
  perform public.log_product_event(new.user_id, 'assessment_submitted',
    jsonb_build_object('assessment_id', new.id, 'measured_fields', v_measured, 'is_reassessment', v_prior > 0, 'prior_count', v_prior),
    new.sport);
  return new;
end; $function$

CREATE OR REPLACE FUNCTION public.tg_pe_user_base_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.base_status is distinct from old.base_status then
    perform public.log_product_event(new.id, 'base_status_changed',
      jsonb_build_object('from', old.base_status, 'to', new.base_status, 'base_expiry', new.base_expiry), new.active_sport);
    if new.base_status = 'active' then
      perform public.log_product_event(new.id, 'base_activated', jsonb_build_object('base_expiry', new.base_expiry), new.active_sport);
    end if;
  end if;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION public.romood_purge_expired(mode text DEFAULT 'until_delete'::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n integer := 0;
begin
  if mode = 'until_delete' then return 0;
  elsif mode = '12_months' then delete from public.mood_entries where created_at < now() - interval '12 months';
  elsif mode = 'rolling_12_weeks' then delete from public.mood_entries where created_at < now() - interval '12 weeks';
  else raise exception 'unknown retention mode %', mode;
  end if;
  get diagnostics n = row_count;
  return n;
end $function$

CREATE OR REPLACE FUNCTION public.romood_enforce_daily_cap()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  day_start timestamptz;
  n integer;
begin
  perform pg_advisory_xact_lock(hashtextextended('romood_daily_cap:' || new.user_id::text, 0));
  -- Ignore any created_at the client sends (backdated or future). The row is stamped with server time,
  -- so the day count below, the cap, and the email window cannot be skipped by faking a time.
  new.created_at := now();
  day_start := (date_trunc('day', now() at time zone 'America/New_York')) at time zone 'America/New_York';
  select count(*) into n
    from public.mood_entries
   where user_id = new.user_id
     and created_at >= day_start
     and created_at < day_start + interval '1 day';
  if n >= 4 then
    raise exception using errcode = 'RM429', message = 'romood_daily_cap',
      detail = 'Mood check-ins are limited to 4 per day (America/New_York).';
  end if;
  return new;
end;
$function$

