CREATE OR REPLACE FUNCTION public.ensure_public_user_profile(p_id uuid, p_email text, p_meta jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_full_name text := coalesce(
    nullif(trim(p_meta->>'full_name'), ''),
    split_part(p_email, '@', 1)
  );
  v_sport text := coalesce(nullif(p_meta->>'active_sport', ''), 'general');
  v_bb_tier text := nullif(p_meta->>'active_bb_tier', '');
  v_belt text := nullif(p_meta->>'belt', '');
  v_signup_source text := nullif(trim(p_meta->>'signup_source'), '');
  v_utm_source text := nullif(trim(p_meta->>'utm_source'), '');
  v_utm_medium text := nullif(trim(p_meta->>'utm_medium'), '');
  v_utm_campaign text := nullif(trim(p_meta->>'utm_campaign'), '');
  v_utm_content text := nullif(trim(p_meta->>'utm_content'), '');
  v_utm_term text := nullif(trim(p_meta->>'utm_term'), '');
BEGIN
  IF p_id IS NULL OR p_email IS NULL THEN
    RETURN;
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.sport_config sc WHERE sc.slug = v_sport) THEN
    v_sport := 'general';
  END IF;

  IF v_bb_tier IS NOT NULL
     AND v_bb_tier NOT IN ('beginner', 'intermediate', 'advanced') THEN
    v_bb_tier := NULL;
  END IF;

  IF v_belt IS NOT NULL
     AND v_belt NOT IN ('white', 'blue', 'purple', 'brown', 'black') THEN
    v_belt := NULL;
  END IF;

  IF v_signup_source IS NULL AND v_utm_source IS NOT NULL THEN
    v_signup_source := v_utm_source;
  END IF;

  INSERT INTO public.athletes (user_id, email, full_name)
  VALUES (p_id, p_email, v_full_name)
  ON CONFLICT (user_id) DO NOTHING;

  INSERT INTO public.users (
    id, email, full_name, belt,
    active_sport, active_bb_tier,
    platforms, sports_enabled,
    portal_role, subscription_status, subscription_tier, base_status,
    signup_source, utm_source, utm_medium, utm_campaign, utm_content, utm_term
  )
  VALUES (
    p_id, p_email, v_full_name, v_belt,
    v_sport, v_bb_tier,
    ARRAY['general']::text[], ARRAY['general']::text[],
    'athlete', 'inactive', 'free', 'inactive',
    v_signup_source, v_utm_source, v_utm_medium, v_utm_campaign, v_utm_content, v_utm_term
  )
  ON CONFLICT (id) DO UPDATE
    SET email          = EXCLUDED.email,
        full_name      = COALESCE(EXCLUDED.full_name, public.users.full_name),
        belt           = COALESCE(public.users.belt, EXCLUDED.belt),
        active_sport   = CASE
                           WHEN public.users.active_sport IS NULL
                             OR public.users.active_sport = 'general'
                           THEN EXCLUDED.active_sport
                           ELSE public.users.active_sport
                         END,
        active_bb_tier = COALESCE(public.users.active_bb_tier, EXCLUDED.active_bb_tier),
        signup_source  = COALESCE(public.users.signup_source, EXCLUDED.signup_source),
        utm_source     = COALESCE(public.users.utm_source, EXCLUDED.utm_source),
        utm_medium     = COALESCE(public.users.utm_medium, EXCLUDED.utm_medium),
        utm_campaign   = COALESCE(public.users.utm_campaign, EXCLUDED.utm_campaign),
        utm_content    = COALESCE(public.users.utm_content, EXCLUDED.utm_content),
        utm_term       = COALESCE(public.users.utm_term, EXCLUDED.utm_term);
END;
$function$

CREATE OR REPLACE FUNCTION public.purge_ai_chats_90d()
 RETURNS TABLE(messages_deleted bigint, conversations_deleted bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  cutoff timestamptz := now() - interval '90 days';
  m bigint;
  c bigint;
begin
  -- Messages first (children of ai_conversations).
  delete from public.ai_messages where created_at < cutoff;
  get diagnostics m = row_count;

  -- Conversations whose last activity is older than 90 days and that have no newer messages.
  delete from public.ai_conversations conv
  where greatest(conv.created_at, coalesce(conv.updated_at, conv.created_at)) < cutoff
    and not exists (
      select 1 from public.ai_messages msg
      where msg.conversation_id = conv.id and msg.created_at >= cutoff
    );
  get diagnostics c = row_count;

  return query select m, c;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_coaches_self_grant()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  -- Only direct API writes are checked (same test as guard_athletes_coach_id). service_role, migrations and the invite flow pass.
  IF coalesce(current_setting('role', true), 'none') NOT IN ('authenticated', 'anon') THEN RETURN NEW; END IF;
  IF auth.uid() IS NULL OR NEW.user_id IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'coaches: a coach row can only be your own' USING errcode = '42501';
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.user_id IS DISTINCT FROM OLD.user_id THEN
    RAISE EXCEPTION 'coaches: user_id cannot change' USING errcode = '42501';
  END IF;
  -- portal_role and school_id on users are protected columns (service role / admin only), so these two checks cannot be self-set.
  IF NOT EXISTS (SELECT 1 FROM public.users u WHERE u.id = NEW.user_id AND u.portal_role = 'coach'
                 AND NEW.school_id IS NOT DISTINCT FROM u.school_id) THEN
    RAISE EXCEPTION 'coaches: coach role and school are assigned by ROMRx, not self-set' USING errcode = '42501',
      HINT = 'Ask support to enable the coach account.';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.notif_opt_in_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if current_user in ('anon', 'authenticated') then
    if tg_op = 'INSERT' then
      new.retest_opt_in_at := null; new.protocol_opt_in_at := null; new.digest_opt_in_at := null;
    else
      new.retest_opt_in_at := old.retest_opt_in_at; new.protocol_opt_in_at := old.protocol_opt_in_at; new.digest_opt_in_at := old.digest_opt_in_at;
    end if;
  end if;
  if new.retest_reminders   is not true then new.retest_opt_in_at   := null; end if;
  if new.email_reminders    is not true then new.protocol_opt_in_at := null; end if;
  if new.weekly_digest      is not true then new.digest_opt_in_at   := null; end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.set_reminder_opt_in(p_kind text, p_on boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare uid uuid := auth.uid();
begin
  if uid is null then raise exception 'not_authenticated' using errcode = '28000'; end if;
  if p_kind not in ('retest', 'protocol', 'digest') or p_on is null then raise exception 'bad_argument' using errcode = '22023'; end if;
  insert into public.notification_preferences(user_id) values (uid) on conflict (user_id) do nothing;
  if p_kind = 'retest' then
    update public.notification_preferences set retest_reminders = p_on, retest_opt_in_at = case when p_on then coalesce(retest_opt_in_at, now()) else null end where user_id = uid;
  elsif p_kind = 'protocol' then
    update public.notification_preferences set email_reminders = p_on, protocol_opt_in_at = case when p_on then coalesce(protocol_opt_in_at, now()) else null end where user_id = uid;
  else
    update public.notification_preferences set weekly_digest = p_on, digest_opt_in_at = case when p_on then coalesce(digest_opt_in_at, now()) else null end where user_id = uid;
  end if;
end $function$

CREATE OR REPLACE FUNCTION public.get_my_coach()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_coach_id uuid;
  v_coach_user_id uuid;
  v_full_name text;
  v_email text;
BEGIN
  IF v_uid IS NULL THEN RETURN NULL; END IF;
  SELECT a.coach_id INTO v_coach_id FROM public.athletes a WHERE a.user_id = v_uid;
  IF v_coach_id IS NULL THEN RETURN NULL; END IF;
  SELECT c.user_id INTO v_coach_user_id FROM public.coaches c WHERE c.id = v_coach_id;
  IF v_coach_user_id IS NULL THEN RETURN NULL; END IF;
  SELECT u.full_name, u.email INTO v_full_name, v_email FROM public.users u WHERE u.id = v_coach_user_id;
  IF v_email IS NULL OR v_full_name IS NULL THEN
    SELECT
      COALESCE(v_full_name, au.raw_user_meta_data->>'full_name'),
      COALESCE(v_email, au.email)
    INTO v_full_name, v_email
    FROM auth.users au WHERE au.id = v_coach_user_id;
  END IF;
  RETURN jsonb_build_object('id', v_coach_id, 'full_name', v_full_name, 'email', v_email);
END;
$function$

CREATE OR REPLACE FUNCTION public.get_my_profile()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid UUID := auth.uid();
  v_profile JSONB;
  v_assessment JSONB;
  v_assessments JSONB;
  v_eligibility JSONB;
  v_sport_entitlements JSONB;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('error', 'Not authenticated');
  END IF;

  SELECT to_jsonb(u) INTO v_profile FROM public.users u WHERE u.id = v_uid;

  SELECT to_jsonb(a) INTO v_assessment
    FROM public.assessments a
    WHERE a.user_id = v_uid
    ORDER BY a.assessed_at DESC
    LIMIT 1;

  SELECT jsonb_agg(to_jsonb(a) ORDER BY a.assessed_at DESC) INTO v_assessments
    FROM (
      SELECT * FROM public.assessments a
      WHERE a.user_id = v_uid
      ORDER BY a.assessed_at DESC
      LIMIT 4
    ) a;

  -- BJJ "My Game" only. The techniques + technique_eligibility tables are shared
  -- across sports (Base ROM architecture); +Bodybuilding rows must not leak into
  -- the BJJ view. +Bodybuilding uses its own app and never calls this function.
  SELECT jsonb_agg(
    jsonb_build_object(
      'id', te.id, 'technique_id', te.technique_id, 'technique_code', te.technique_code,
      'tier', te.tier, 'flag', te.flag, 'limiting_joints', te.limiting_joints,
      'techniques', jsonb_build_object('code', t.code, 'name', t.name, 'belt', t.belt, 'category', t.category)
    ) ORDER BY te.tier
  ) INTO v_eligibility
    FROM public.technique_eligibility te
    LEFT JOIN public.techniques t ON t.id = te.technique_id
    WHERE te.user_id = v_uid
      AND te.sport = 'bjj';

  SELECT jsonb_agg(
    jsonb_build_object(
      'sport', se.sport,
      'status', se.status,
      'stripe_subscription_id', se.stripe_subscription_id,
      'granted_at', se.granted_at,
      'expires_at', se.expires_at
    ) ORDER BY se.granted_at DESC
  ) INTO v_sport_entitlements
    FROM public.sport_entitlements se
    WHERE se.user_id = v_uid;

  RETURN jsonb_build_object(
    'profile', v_profile,
    'assessment', v_assessment,
    'assessments', COALESCE(v_assessments, '[]'::jsonb),
    'eligibility', COALESCE(v_eligibility, '[]'::jsonb),
    'sport_entitlements', COALESCE(v_sport_entitlements, '[]'::jsonb)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.handle_auth_user_updated()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.users u WHERE u.id = NEW.id) THEN
    PERFORM public.ensure_public_user_profile(
      NEW.id, NEW.email, coalesce(NEW.raw_user_meta_data, '{}'::jsonb)
    );
  ELSIF NEW.email IS DISTINCT FROM OLD.email THEN
    UPDATE public.users
    SET email = NEW.email,
        updated_at = NOW()
    WHERE id = NEW.id;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.sync_user_sports()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.platforms IS DISTINCT FROM OLD.platforms AND NEW.sports_enabled IS NOT DISTINCT FROM OLD.sports_enabled THEN
    NEW.sports_enabled := NEW.platforms;
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.sports_enabled IS DISTINCT FROM OLD.sports_enabled AND NEW.platforms IS NOT DISTINCT FROM OLD.platforms THEN
    NEW.platforms := NEW.sports_enabled;
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF NEW.platforms IS NOT NULL AND cardinality(NEW.platforms) > 0 AND NEW.sports_enabled IS NULL THEN
      NEW.sports_enabled := NEW.platforms;
    ELSIF NEW.sports_enabled IS NOT NULL AND cardinality(NEW.sports_enabled) > 0 AND (NEW.platforms IS NULL OR cardinality(NEW.platforms) = 0) THEN
      NEW.platforms := NEW.sports_enabled;
    END IF;
  END IF;
  IF NEW.sports_enabled IS NOT NULL AND cardinality(NEW.sports_enabled) > 0
     AND NOT (NEW.active_sport = ANY (NEW.sports_enabled)) AND NEW.active_sport <> 'general' THEN
    NEW.active_sport := NEW.sports_enabled[1];
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.export_my_backup_page(p_key text, p_offset integer, p_limit integer)
 RETURNS SETOF jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare uid uuid := auth.uid(); lim int := least(greatest(coalesce(p_limit, 1000), 1), 1000); off int := greatest(coalesce(p_offset, 0), 0);
begin
  if uid is null then raise exception 'not signed in' using errcode = '28000'; end if;
  -- Stacy 7:24 PM: once a safety-copy table is dropped its section is simply empty (never an error, so the export stays complete).
  if p_key in ('lumbar_null_backup_20261021_assessments','lumbar_null_backup_20261021_joint_scores','lumbar_null_backup_20261021_protocols',
               'rescore_backup_20261021_assessments','rescore_backup_20261021_joint_scores','rescore_backup_20261021_protocols','fg36_rescore_backup','fg36_rescore_log')
     and to_regclass('public.' || p_key) is null then return; end if;
  if p_key = 'lumbar_null_backup_20261021_assessments' then
    return query select jsonb_build_object('id', b.id, 'lumbar_flex', b.lumbar_flex, 'lumbar_ext', b.lumbar_ext)
      from public.lumbar_null_backup_20261021_assessments b join public.assessments a on a.id = b.id
      where a.user_id = uid order by b.id offset off limit lim;
  elsif p_key = 'lumbar_null_backup_20261021_joint_scores' then
    return query select jsonb_build_object('id', b.id, 'assessment_id', b.assessment_id, 'joint_key', b.joint_key, 'score', b.score, 'left_value', b.left_value,
        'right_value', b.right_value, 'asymmetry_pct', b.asymmetry_pct, 'asymmetry_flag', b.asymmetry_flag, 'created_at', b.created_at)
      from public.lumbar_null_backup_20261021_joint_scores b join public.assessments a on a.id = b.assessment_id
      where a.user_id = uid order by b.created_at, b.id offset off limit lim;
  elsif p_key = 'lumbar_null_backup_20261021_protocols' then
    return query select jsonb_build_object('id', b.id, 'assessment_id', b.assessment_id, 'exercise_id', b.exercise_id, 'joint_key', b.joint_key,
        'priority_rank', b.priority_rank, 'created_at', b.created_at)
      from public.lumbar_null_backup_20261021_protocols b where b.user_id = uid order by b.created_at, b.id offset off limit lim;
  elsif p_key = 'rescore_backup_20261021_assessments' then
    return query select jsonb_build_object('id', b.id, 'assessed_at', b.assessed_at, 'sport', b.sport, 'rom_total', b.rom_total, 'rom_percentile', b.rom_percentile,
        'worst_joints', b.worst_joints, 'red_flag_triggered', b.red_flag_triggered, 'red_flag_reasons', b.red_flag_reasons, 'created_at', b.created_at,
        'hip_er_l', b.hip_er_l, 'hip_er_r', b.hip_er_r, 'hip_ir_l', b.hip_ir_l, 'hip_ir_r', b.hip_ir_r, 'hip_abd_l', b.hip_abd_l, 'hip_abd_r', b.hip_abd_r,
        'hip_flex_l', b.hip_flex_l, 'hip_flex_r', b.hip_flex_r, 'hip_ext_l', b.hip_ext_l, 'hip_ext_r', b.hip_ext_r,
        'shoulder_er_l', b.shoulder_er_l, 'shoulder_er_r', b.shoulder_er_r, 'shoulder_flex_l', b.shoulder_flex_l, 'shoulder_flex_r', b.shoulder_flex_r,
        'ankle_df_l', b.ankle_df_l, 'ankle_df_r', b.ankle_df_r, 'cervical_rot_l', b.cervical_rot_l, 'cervical_rot_r', b.cervical_rot_r,
        'cervical_lat_l', b.cervical_lat_l, 'cervical_lat_r', b.cervical_lat_r, 'cervical_flex', b.cervical_flex, 'cervical_ext', b.cervical_ext,
        'lumbar_flex', b.lumbar_flex, 'lumbar_ext', b.lumbar_ext, 'thoracic_rot', b.thoracic_rot, 'thoracic_rot_l', b.thoracic_rot_l, 'thoracic_rot_r', b.thoracic_rot_r,
        'balance_l', b.balance_l, 'balance_r', b.balance_r)
      from public.rescore_backup_20261021_assessments b where b.user_id = uid order by b.assessed_at, b.id offset off limit lim;
  elsif p_key = 'rescore_backup_20261021_joint_scores' then
    return query select jsonb_build_object('id', b.id, 'assessment_id', b.assessment_id, 'joint_key', b.joint_key, 'score', b.score, 'left_value', b.left_value,
        'right_value', b.right_value, 'asymmetry_pct', b.asymmetry_pct, 'asymmetry_flag', b.asymmetry_flag, 'created_at', b.created_at)
      from public.rescore_backup_20261021_joint_scores b
      where b.assessment_id in (select a.id from public.assessments a where a.user_id = uid
                                union select r.id from public.rescore_backup_20261021_assessments r where r.user_id = uid)
      order by b.created_at, b.id offset off limit lim;
  elsif p_key = 'rescore_backup_20261021_protocols' then
    return query select jsonb_build_object('id', b.id, 'assessment_id', b.assessment_id, 'exercise_id', b.exercise_id, 'joint_key', b.joint_key,
        'priority_rank', b.priority_rank, 'created_at', b.created_at)
      from public.rescore_backup_20261021_protocols b where b.user_id = uid order by b.created_at, b.id offset off limit lim;
  elsif p_key = 'fg36_rescore_backup' then
    -- the caller's rows only, found through the log (the backup has only assessment_id). Cutover rows are not user data and are not returned. user_id and athlete_id are stripped.
    return query select jsonb_build_object('run_id', b.run_id, 'assessment_id', b.assessment_id, 'created_at', b.created_at,
        'rom_total', b.payload->'rom_total', 'worst_joints', b.payload->'worst_joints', 'joint_scores', b.payload->'joint_scores',
        'protocols', (select coalesce(jsonb_agg(e - 'user_id' - 'athlete_id' order by ord), '[]'::jsonb) from jsonb_array_elements(coalesce(b.payload->'protocols','[]'::jsonb)) with ordinality as t(e, ord)))
      from public.fg36_rescore_backup b
      where b.kind = 'assessment' and exists (select 1 from public.fg36_rescore_log l where l.user_id = uid and l.assessment_id = b.assessment_id and l.run_id = b.run_id)
      order by b.created_at, b.run_id, b.assessment_id offset off limit lim;
  elsif p_key = 'fg36_rescore_log' then
    return query select jsonb_build_object('run_id', l.run_id, 'assessment_id', l.assessment_id, 'joint_score_id', l.joint_score_id, 'left_value', l.left_value, 'right_value', l.right_value,
        'target', l.target, 'score', l.score, 'applied_at', l.applied_at, 'rolled_back_at', l.rolled_back_at, 'rom_total_before', l.rom_total_before, 'rom_total_after', l.rom_total_after,
        'worst_before', l.worst_before, 'worst_after', l.worst_after, 'protocols_before', l.protocols_before, 'protocols_after', l.protocols_after)
      from public.fg36_rescore_log l where l.user_id = uid order by l.applied_at, l.run_id, l.assessment_id, l.joint_score_id offset off limit lim;
  else
    raise exception 'unknown backup key' using errcode = '22023';
  end if;
end $function$

