CREATE OR REPLACE FUNCTION public.log_set(p_workout_id uuid, p_exercise_id uuid, p_exercise_name text, p_set_index integer, p_weight_kg numeric, p_reps integer, p_rpe numeric DEFAULT NULL::numeric, p_rir integer DEFAULT NULL::integer, p_is_warmup boolean DEFAULT false, p_notes text DEFAULT NULL::text, p_technique_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid           uuid := auth.uid();
  v_set_id        uuid;
  v_e1rm          numeric;
  v_existing_e1rm numeric;
  v_new_pr        boolean := false;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'not authenticated'; END IF;

  INSERT INTO workout_sets (
    user_id, workout_id, exercise_id, technique_id, exercise_name,
    set_index, weight_kg, reps, rpe, rir, is_warmup, notes
  ) VALUES (
    v_uid, p_workout_id, p_exercise_id, p_technique_id, p_exercise_name,
    p_set_index, p_weight_kg, p_reps, p_rpe, p_rir, p_is_warmup, p_notes
  ) RETURNING id INTO v_set_id;

  -- Skip PR processing for warmup sets or sets without load/reps.
  IF p_is_warmup OR p_weight_kg IS NULL OR p_reps IS NULL OR p_reps <= 0 THEN
    RETURN jsonb_build_object('set_id', v_set_id, 'pr', false);
  END IF;

  -- Epley estimated 1RM:  w * (1 + reps/30)
  v_e1rm := round(p_weight_kg * (1 + p_reps::numeric / 30.0), 2);

  SELECT estimated_1rm_kg INTO v_existing_e1rm
    FROM pr_records
   WHERE user_id = v_uid AND exercise_name = p_exercise_name AND pr_type = 'estimated_1rm';

  IF v_existing_e1rm IS NULL OR v_e1rm > v_existing_e1rm THEN
    INSERT INTO pr_records (user_id, exercise_name, technique_id, pr_type, weight_kg, reps, estimated_1rm_kg, set_id)
    VALUES (v_uid, p_exercise_name, p_technique_id, 'estimated_1rm', p_weight_kg, p_reps, v_e1rm, v_set_id)
    ON CONFLICT (user_id, exercise_name, pr_type) DO UPDATE
      SET weight_kg = EXCLUDED.weight_kg,
          reps = EXCLUDED.reps,
          estimated_1rm_kg = EXCLUDED.estimated_1rm_kg,
          set_id = EXCLUDED.set_id,
          achieved_at = now();
    v_new_pr := true;
  END IF;

  RETURN jsonb_build_object('set_id', v_set_id, 'pr', v_new_pr, 'estimated_1rm_kg', v_e1rm);
END;
$function$

CREATE OR REPLACE FUNCTION public.purge_account_deletion_requests(p_retention interval)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare n integer;
begin
  if p_retention is null then raise exception 'retention period required (Jim sets it)'; end if;
  -- Guard against a typo wiping the proof of deletion: the processing window is 30 days, so the log is never purged sooner than that.
  if p_retention < interval '30 days' then raise exception 'retention below 30 days refused'; end if;
  delete from public.account_deletion_requests where status = 'completed' and completed_at is not null and completed_at < now() - p_retention;
  get diagnostics n = row_count;
  return n;
end $function$

