CREATE OR REPLACE FUNCTION public.erase_fg36_rescore_data(p_user uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare n integer := 0; k integer;
begin
  if p_user is null then raise exception 'user id required'; end if;
  if to_regclass('public.fg36_rescore_log') is null or to_regclass('public.fg36_rescore_backup') is null then return 0; end if;
  execute 'delete from public.fg36_rescore_backup b using public.fg36_rescore_log l where l.user_id = $1 and b.assessment_id = l.assessment_id and b.run_id = l.run_id' using p_user;
  get diagnostics k = row_count; n := n + k;
  execute 'delete from public.fg36_rescore_log where user_id = $1' using p_user;
  get diagnostics k = row_count; n := n + k;
  return n;
end $function$

CREATE OR REPLACE FUNCTION public.erase_backup_copies_for_user(p_user uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare ids uuid[]; extra uuid[]; r jsonb := '{}'::jsonb; k int; total int := 0; fg int := 0;
  la text := 'public.lumbar_null_backup_20261021_assessments'; lj text := 'public.lumbar_null_backup_20261021_joint_scores'; lp text := 'public.lumbar_null_backup_20261021_protocols';
  ra text := 'public.rescore_backup_20261021_assessments'; rj text := 'public.rescore_backup_20261021_joint_scores'; rp text := 'public.rescore_backup_20261021_protocols';
begin
  if p_user is null then raise exception 'user id required'; end if;
  -- 1. collect the safe key BEFORE deleting anything
  ids := coalesce(array(select a.id from public.assessments a where a.user_id = p_user), '{}');
  if to_regclass(ra) is not null then
    execute 'select coalesce(array_agg(id), ''{}'') from ' || ra || ' where user_id = $1' into extra using p_user; ids := ids || extra;
  end if;
  if to_regclass(lp) is not null then
    execute 'select coalesce(array_agg(assessment_id), ''{}'') from ' || lp || ' where user_id = $1 and assessment_id is not null' into extra using p_user; ids := ids || extra;
  end if;
  if to_regclass(rp) is not null then
    execute 'select coalesce(array_agg(assessment_id), ''{}'') from ' || rp || ' where user_id = $1 and assessment_id is not null' into extra using p_user; ids := ids || extra;
  end if;
  ids := coalesce(array(select distinct x from unnest(ids) x), '{}');
  -- 2. delete: lumbar copies first (no user_id), children before parents
  if to_regclass(lj) is not null then execute 'delete from ' || lj || ' where assessment_id = any($1)' using ids; get diagnostics k = row_count; else k := 0; end if;
  r := r || jsonb_build_object('lumbar_null_backup_20261021_joint_scores', k); total := total + k;
  if to_regclass(la) is not null then execute 'delete from ' || la || ' where id = any($1)' using ids; get diagnostics k = row_count; else k := 0; end if;
  r := r || jsonb_build_object('lumbar_null_backup_20261021_assessments', k); total := total + k;
  if to_regclass(lp) is not null then execute 'delete from ' || lp || ' where user_id = $1 or assessment_id = any($2)' using p_user, ids; get diagnostics k = row_count; else k := 0; end if;
  r := r || jsonb_build_object('lumbar_null_backup_20261021_protocols', k); total := total + k;
  if to_regclass(rj) is not null then execute 'delete from ' || rj || ' where assessment_id = any($1)' using ids; get diagnostics k = row_count; else k := 0; end if;
  r := r || jsonb_build_object('rescore_backup_20261021_joint_scores', k); total := total + k;
  if to_regclass(rp) is not null then execute 'delete from ' || rp || ' where user_id = $1 or assessment_id = any($2)' using p_user, ids; get diagnostics k = row_count; else k := 0; end if;
  r := r || jsonb_build_object('rescore_backup_20261021_protocols', k); total := total + k;
  if to_regclass(ra) is not null then execute 'delete from ' || ra || ' where user_id = $1 or id = any($2)' using p_user, ids; get diagnostics k = row_count; else k := 0; end if;
  r := r || jsonb_build_object('rescore_backup_20261021_assessments', k); total := total + k;
  -- 3. the two FG-36 tables (the function returns 0 if they do not exist yet or were dropped)
  if to_regprocedure('public.erase_fg36_rescore_data(uuid)') is not null then fg := public.erase_fg36_rescore_data(p_user); end if;
  r := r || jsonb_build_object('fg36_rescore_backup_and_log', fg); total := total + fg;
  return r || jsonb_build_object('total', total);
end $function$

