CREATE OR REPLACE FUNCTION public.record_signup_terms_consent()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  m jsonb := coalesce(new.raw_user_meta_data, '{}'::jsonb);
  v_terms text := m->>'terms_version';
  v_text text := m->>'consent_text_version';
  v_source text := m->>'consent_source';
begin
  if coalesce(m->>'terms_accepted', '') <> 'true' then
    return new;  -- path did not show our checkbox: record nothing
  end if;
  if v_terms is distinct from public.current_terms_version() then
    raise exception 'terms record: version % is not current', coalesce(v_terms, 'null') using errcode = '22023';
  end if;
  if not public.allowed_consent_text_version(v_text) then
    raise exception 'terms record: unknown consent_text_version' using errcode = '22023';
  end if;
  if not coalesce(public.allowed_signup_consent(v_source, v_text), false) then
    raise exception 'terms record: unknown source for this checkbox' using errcode = '22023';
  end if;

  insert into public.consents (
    user_id, terms_version, medical_waiver_version, signed_name,
    ip_address, user_agent, signed_at, consent_text_version, source
  ) values (
    new.id, v_terms, v_terms,
    coalesce(nullif(trim(m->>'full_name'), ''), split_part(new.email, '@', 1), 'unknown'),
    null, left(nullif(m->>'consent_user_agent', ''), 512), now(), v_text, v_source
  );
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.record_terms_reaccept(p_terms_version text, p_consent_text_version text, p_source text, p_user_agent text)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_name text;
  v_at timestamptz := now();
begin
  if v_uid is null then
    raise exception 'not signed in' using errcode = '42501';
  end if;
  if p_terms_version is distinct from public.current_terms_version() then
    raise exception 'terms record: version is not current' using errcode = '22023';
  end if;
  if p_consent_text_version is distinct from 'signup-checkbox-2026-10-05' then
    raise exception 'terms record: unknown consent_text_version' using errcode = '22023';
  end if;
  if not coalesce(public.allowed_reaccept_source(p_source), false) then
    raise exception 'terms record: unknown source' using errcode = '22023';
  end if;
  -- Idempotent: one current-version row is enough.
  if exists (select 1 from public.consents where user_id = v_uid and terms_version = p_terms_version) then
    select max(signed_at) into v_at from public.consents where user_id = v_uid and terms_version = p_terms_version;
    return v_at;
  end if;
  select coalesce(nullif(trim(u.full_name), ''), split_part(u.email, '@', 1), 'unknown')
    into v_name from public.users u where u.id = v_uid;
  insert into public.consents (
    user_id, terms_version, medical_waiver_version, signed_name,
    ip_address, user_agent, signed_at, consent_text_version, source
  ) values (
    v_uid, p_terms_version, p_terms_version, coalesce(v_name, 'unknown'),
    null, left(nullif(p_user_agent, ''), 512), v_at, p_consent_text_version, p_source
  );
  return v_at;
end;
$function$

CREATE OR REPLACE FUNCTION public.copy_signup_demographics()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  m jsonb := coalesce(new.raw_user_meta_data, '{}'::jsonb);
  v_age text := nullif(m->>'age_bucket', '');
  v_gender text := nullif(m->>'gender', '');
begin
  if v_age is not null and v_age not in ('18-29', '30-44', '45-59', '60+') then v_age := null; end if;
  if v_gender is not null and v_gender not in ('male', 'female', 'other', 'prefer_not_to_say') then v_gender := null; end if;
  if v_age is null and v_gender is null then return new; end if;
  update public.users
     set age_bucket = coalesce(age_bucket, v_age),
         gender     = coalesce(gender, v_gender)
   where id = new.id;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.connect_coach_by_email(p_email text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_coach_user_id uuid;
  v_coach_id uuid;
  v_full_name text;
  v_rows int;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_authenticated');
  END IF;
  SELECT u.id, u.full_name INTO v_coach_user_id, v_full_name
  FROM public.users u
  WHERE lower(u.email) = lower(trim(coalesce(p_email, '')))
    AND u.portal_role = 'coach'
  LIMIT 1;
  IF v_coach_user_id IS NOT NULL THEN
    SELECT c.id INTO v_coach_id FROM public.coaches c WHERE c.user_id = v_coach_user_id LIMIT 1;
  END IF;
  IF v_coach_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;
  IF v_coach_user_id = v_uid THEN
    RETURN jsonb_build_object('ok', false, 'error', 'self');
  END IF;
  -- Tells guard_athletes_coach_id (Phase B) this write came through this function. Transaction-local; clients
  -- cannot set it (pg_catalog.set_config is not exposed through the API).
  PERFORM set_config('romrx.coach_connect', v_coach_id::text, true);
  UPDATE public.athletes SET coach_id = v_coach_id, updated_at = now() WHERE user_id = v_uid;
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows = 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'no_athlete_profile');
  END IF;
  IF v_full_name IS NULL THEN
    SELECT au.raw_user_meta_data->>'full_name' INTO v_full_name FROM auth.users au WHERE au.id = v_coach_user_id;
  END IF;
  -- Caller is now linked, so the coach's display name may be shown.
  RETURN jsonb_build_object('ok', true, 'coach_name', v_full_name);
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_athletes_coach_id()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  -- Only direct API writes are checked. current_setting('role') is the PostgREST role and stays the same inside
  -- SECURITY DEFINER functions (same test the coaches service policy uses). service_role, migrations and the FK's
  -- ON DELETE SET NULL pass.
  if coalesce(current_setting('role', true), 'none') not in ('authenticated', 'anon') then
    return new;
  end if;
  if new.coach_id is not distinct from old.coach_id then
    return new;
  end if;
  if new.coach_id is null then
    return new;  -- unlink / Disconnect always allowed
  end if;
  if current_setting('romrx.coach_connect', true) = new.coach_id::text then
    return new;  -- set by connect_coach_by_email in this transaction
  end if;
  -- SECURITY DEFINER so this lookup can see coaches/users (athletes cannot read other users' rows under RLS).
  if not exists (
    select 1
    from public.coaches c
    join public.users u on u.id = c.user_id
    where c.id = new.coach_id
      and u.portal_role = 'coach'
      and c.user_id is distinct from auth.uid()
  ) then
    raise exception 'athletes: coach_id must be an existing coach'
      using errcode = '42501', hint = 'Connect a coach with connect_coach_by_email.';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_my_bb_tier(p_tier text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_has_bb boolean := false;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Not authenticated');
  END IF;
  IF p_tier NOT IN ('beginner','intermediate','advanced') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Invalid tier');
  END IF;

  SELECT
    COALESCE(u.sports_enabled, ARRAY[]::text[]) @> ARRAY['bodybuilding']::text[]
    OR EXISTS (
      SELECT 1 FROM public.sport_entitlements se
      WHERE se.user_id = v_uid
        AND se.sport = 'bodybuilding'
        AND se.status IN ('active', 'trialing')
    )
  INTO v_has_bb
  FROM public.users u
  WHERE u.id = v_uid;

  IF v_has_bb IS NOT TRUE THEN
    RETURN jsonb_build_object('ok', false, 'error', 'bodybuilding_entitlement_required');
  END IF;

  UPDATE public.users
  SET active_bb_tier = p_tier,
      updated_at = now()
  WHERE id = v_uid;

  RETURN jsonb_build_object('ok', true, 'tier', p_tier);
END;
$function$

CREATE OR REPLACE FUNCTION public.rate_limit_hit(p_key text, p_limit integer, p_window_ms bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_row public.rate_limit_buckets%ROWTYPE;
  v_reset timestamptz;
  v_remaining int;
BEGIN
  v_reset := v_now + (p_window_ms || ' milliseconds')::interval;
  INSERT INTO public.rate_limit_buckets(bucket_key, hit_count, reset_at)
  VALUES (p_key, 0, v_reset)
  ON CONFLICT (bucket_key) DO NOTHING;

  SELECT * INTO v_row FROM public.rate_limit_buckets WHERE bucket_key = p_key FOR UPDATE;

  IF v_row.reset_at <= v_now THEN
    v_row.hit_count := 0;
    v_row.reset_at := v_reset;
  END IF;

  IF v_row.hit_count >= p_limit THEN
    UPDATE public.rate_limit_buckets SET hit_count = v_row.hit_count, reset_at = v_row.reset_at WHERE bucket_key = p_key;
    RETURN jsonb_build_object(
      'allowed', false,
      'limit', p_limit,
      'remaining', 0,
      'reset_at', floor(extract(epoch from v_row.reset_at)*1000)
    );
  END IF;

  v_row.hit_count := v_row.hit_count + 1;
  UPDATE public.rate_limit_buckets SET hit_count = v_row.hit_count, reset_at = v_row.reset_at WHERE bucket_key = p_key;
  v_remaining := GREATEST(0, p_limit - v_row.hit_count);
  RETURN jsonb_build_object(
    'allowed', true,
    'limit', p_limit,
    'remaining', v_remaining,
    'reset_at', floor(extract(epoch from v_row.reset_at)*1000)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.find_coach_by_email(p_email text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_coach_user_id uuid;
  v_coach_id uuid;
  v_full_name text;
  v_email text;
BEGIN
  SELECT id, full_name, email INTO v_coach_user_id, v_full_name, v_email
  FROM public.users
  WHERE lower(email) = lower(trim(coalesce(p_email, '')))
    AND portal_role = 'coach'
  LIMIT 1;

  IF v_coach_user_id IS NULL THEN
    RETURN jsonb_build_object('found', false);
  END IF;

  SELECT id INTO v_coach_id
  FROM public.coaches
  WHERE user_id = v_coach_user_id
  LIMIT 1;

  IF v_coach_id IS NULL THEN
    RETURN jsonb_build_object('found', false, 'reason', 'coach_row_missing');
  END IF;

  IF v_full_name IS NULL THEN
    SELECT au.raw_user_meta_data->>'full_name' INTO v_full_name FROM auth.users au WHERE au.id = v_coach_user_id;
  END IF;

  RETURN jsonb_build_object(
    'found', true,
    'coach_id', v_coach_id,
    'user_id', v_coach_user_id,
    'full_name', v_full_name,
    'email', v_email
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.coach_promote_athlete(p_athlete_user_id uuid, p_new_belt text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_coach_user_id uuid := auth.uid();
  v_coach_id uuid;
BEGIN
  IF v_coach_user_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Not authenticated');
  END IF;
  -- Verify caller has a coaches row
  SELECT id INTO v_coach_id FROM public.coaches WHERE user_id = v_coach_user_id;
  IF v_coach_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Not a coach');
  END IF;
  -- Verify athlete is on this coach roster
  IF NOT EXISTS (SELECT 1 FROM public.athletes WHERE user_id = p_athlete_user_id AND coach_id = v_coach_id) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Athlete not on your roster');
  END IF;
  -- Check belt is valid
  IF p_new_belt NOT IN ('white','blue','purple','brown','black') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Invalid belt');
  END IF;
  UPDATE public.users SET belt = p_new_belt WHERE id = p_athlete_user_id;
  UPDATE public.athletes SET belt = p_new_belt WHERE user_id = p_athlete_user_id;
  RETURN jsonb_build_object('ok', true, 'new_belt', p_new_belt);
END;
$function$

CREATE OR REPLACE FUNCTION public.log_set(p_workout_id uuid, p_exercise_id uuid, p_exercise_name text, p_set_index integer, p_weight_kg numeric, p_reps integer, p_rpe numeric DEFAULT NULL::numeric, p_rir integer DEFAULT NULL::integer, p_is_warmup boolean DEFAULT false, p_notes text DEFAULT NULL::text, p_technique_id uuid DEFAULT NULL::uuid, p_set_type text DEFAULT 'straight'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid           uuid := auth.uid();
  v_set_id        uuid;
  v_e1rm          numeric;
  v_existing_e1rm numeric;
  v_new_pr        boolean := false;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'not authenticated'; END IF;

  INSERT INTO workout_sets (
    user_id, workout_id, exercise_id, technique_id, exercise_name,
    set_index, weight_kg, reps, rpe, rir, is_warmup, notes, set_type
  ) VALUES (
    v_uid, p_workout_id, p_exercise_id, p_technique_id, p_exercise_name,
    p_set_index, p_weight_kg, p_reps, p_rpe, p_rir, p_is_warmup, p_notes,
    COALESCE(p_set_type, 'straight')
  ) RETURNING id INTO v_set_id;

  IF p_is_warmup OR p_weight_kg IS NULL OR p_reps IS NULL OR p_reps <= 0 THEN
    RETURN jsonb_build_object('set_id', v_set_id, 'pr', false);
  END IF;

  v_e1rm := round(p_weight_kg * (1 + p_reps::numeric / 30.0), 2);

  SELECT estimated_1rm_kg INTO v_existing_e1rm
    FROM pr_records
   WHERE user_id = v_uid AND exercise_name = p_exercise_name AND pr_type = 'estimated_1rm';

  IF v_existing_e1rm IS NULL OR v_e1rm > v_existing_e1rm THEN
    INSERT INTO pr_records (user_id, exercise_name, technique_id, pr_type, weight_kg, reps, estimated_1rm_kg, set_id)
    VALUES (v_uid, p_exercise_name, p_technique_id, 'estimated_1rm', p_weight_kg, p_reps, v_e1rm, v_set_id)
    ON CONFLICT (user_id, exercise_name, pr_type) DO UPDATE
      SET weight_kg = EXCLUDED.weight_kg, reps = EXCLUDED.reps,
          estimated_1rm_kg = EXCLUDED.estimated_1rm_kg, set_id = EXCLUDED.set_id,
          achieved_at = now();
    v_new_pr := true;
  END IF;

  RETURN jsonb_build_object('set_id', v_set_id, 'pr', v_new_pr, 'estimated_1rm_kg', v_e1rm);
END;
$function$

